package hu.endrealms.quest;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The quest tree, read from quests.json inside the mod jar so that client and server always agree on it. The file is
 * generated by tools/gen_quests.py: adding a quest there is all that new content needs.
 */
public final class QuestBook {
	public record Objective(String type, String id, String criterion, int count) {
	}

	public record Reward(String item, int count) {
	}

	public record RecipeView(String kind, List<List<String>> slots, String result) {
	}

	/** pathX and pathY place the quest on the Whole Path tab; suggestedAfter is a link drawn there that locks nothing. */
	public record Quest(String id, String chapter, String icon, float x, float y, List<String> requires, List<Objective> objectives, List<Reward> rewards, int xp, List<RecipeView> recipes,
			float pathX, float pathY, int tier, String suggestedAfter) {
	}

	/** realm: "end" or "sculk", the guide's two big tabs; path: the realm's Whole Path tab, all its quests in one tree. */
	public record Chapter(String id, String icon, String realm, boolean path) {
	}

	/** One stage of a realm's Whole Path tab, starting at column x. */
	public record Tier(int id, float x, String realm) {
	}

	/** The End's Whole Path tab. */
	public static final String WHOLE_PATH = "path";
	public static final List<String> REALMS = List.of("end", "sculk");

	private static final List<Chapter> CHAPTERS = new ArrayList<>();
	private static final List<Tier> TIERS = new ArrayList<>();
	private static final Map<String, Quest> QUESTS = new LinkedHashMap<>();

	static {
		try (InputStream in = QuestBook.class.getResourceAsStream("/data/endrealms/quests.json")) {
			if (in == null) {
				throw new IllegalStateException("quests.json is missing from the mod");
			}
			JsonObject root = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			for (JsonElement e : root.getAsJsonArray("chapters")) {
				JsonObject o = e.getAsJsonObject();
				CHAPTERS.add(new Chapter(o.get("id").getAsString(), o.get("icon").getAsString(),
						o.has("realm") ? o.get("realm").getAsString() : "end", o.has("path") && o.get("path").getAsBoolean()));
			}
			for (JsonElement e : root.getAsJsonArray("tiers")) {
				JsonObject o = e.getAsJsonObject();
				TIERS.add(new Tier(o.get("id").getAsInt(), o.get("x").getAsFloat(), o.has("realm") ? o.get("realm").getAsString() : "end"));
			}
			for (JsonElement e : root.getAsJsonArray("quests")) {
				Quest quest = parse(e.getAsJsonObject());
				QUESTS.put(quest.id(), quest);
			}
		} catch (IOException exception) {
			throw new IllegalStateException("Could not read quests.json", exception);
		}
	}

	private QuestBook() {
	}

	private static List<String> strings(JsonArray array) {
		List<String> list = new ArrayList<>();
		array.forEach(e -> list.add(e.getAsString()));
		return list;
	}

	private static Quest parse(JsonObject o) {
		List<Objective> objectives = new ArrayList<>();
		for (JsonElement e : o.getAsJsonArray("objectives")) {
			JsonObject g = e.getAsJsonObject();
			objectives.add(new Objective(g.get("type").getAsString(), g.get("id").getAsString(), g.has("criterion") ? g.get("criterion").getAsString() : null,
					g.has("count") ? g.get("count").getAsInt() : 1));
		}
		List<Reward> rewards = new ArrayList<>();
		for (JsonElement e : o.getAsJsonArray("rewards")) {
			JsonObject g = e.getAsJsonObject();
			rewards.add(new Reward(g.get("item").getAsString(), g.get("count").getAsInt()));
		}
		List<RecipeView> recipes = new ArrayList<>();
		for (JsonElement e : o.getAsJsonArray("recipes")) {
			JsonObject g = e.getAsJsonObject();
			List<List<String>> slots = new ArrayList<>();
			g.getAsJsonArray("slots").forEach(slot -> slots.add(strings(slot.getAsJsonArray())));
			recipes.add(new RecipeView(g.get("kind").getAsString(), slots, g.get("result").getAsString()));
		}
		return new Quest(o.get("id").getAsString(), o.get("chapter").getAsString(), o.get("icon").getAsString(), o.get("x").getAsFloat(), o.get("y").getAsFloat(),
				strings(o.getAsJsonArray("requires")), objectives, rewards, o.get("xp").getAsInt(), recipes,
				o.get("path_x").getAsFloat(), o.get("path_y").getAsFloat(), o.get("tier").getAsInt(), o.has("after") ? o.get("after").getAsString() : null);
	}

	public static List<Chapter> chapters() {
		return CHAPTERS;
	}

	public static Quest quest(String id) {
		return QUESTS.get(id);
	}

	public static List<Tier> tiers() {
		return TIERS;
	}

	public static Chapter chapter(String id) {
		return CHAPTERS.stream().filter(c -> c.id().equals(id)).findFirst().orElse(null);
	}

	/** The realm a quest belongs to: that of its chapter. */
	public static String realm(Quest quest) {
		Chapter chapter = chapter(quest.chapter());
		return chapter == null ? "end" : chapter.realm();
	}

	public static List<Chapter> chapters(String realm) {
		return CHAPTERS.stream().filter(c -> c.realm().equals(realm)).toList();
	}

	public static List<Tier> tiers(String realm) {
		return TIERS.stream().filter(t -> t.realm().equals(realm)).toList();
	}

	/** A chapter's quests; a Whole Path tab shows every quest of its realm that has a tier. */
	public static List<Quest> inChapter(String chapterId) {
		Chapter chapter = chapter(chapterId);
		if (chapter != null && chapter.path()) {
			return QUESTS.values().stream().filter(q -> q.tier() > 0 && realm(q).equals(chapter.realm())).toList();
		}
		return QUESTS.values().stream().filter(q -> q.chapter().equals(chapterId)).toList();
	}

	public static List<Quest> inRealm(String realm) {
		return QUESTS.values().stream().filter(q -> realm(q).equals(realm)).toList();
	}

	public static int size() {
		return QUESTS.size();
	}
}
